# python3 -I tests/studio_settings_browser.py — the toolbar's tool settings: re-tap / long-press opens #st-toolset,
# pen presets + smoothing + pressure range (persisted, live preview), highlighter opacity / straight line, eraser mode and
# size, arrow heads + angle snap, text size / bold, quick marker colours, lasso restyling, «المزيد» input settings
# (finger, stylus only, palm + sensitivity, two fingers, auto stylus, forget pen), insert image, night mode,
# and the phone bottom sheet (390x844, one-row bar). Needs MEDIXA_CDN_DIR and playwright==1.56.0.
import os, sys, json
sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), 'helpers'))
from studio_env import *
from playwright.sync_api import sync_playwright
PORT = 8841 + PORT_OFFSET; BASE = f'http://localhost:{PORT}/'; srv = start_server(PORT); chk = Checker('STUDIO SETTINGS')
URL = 'files/uploaded/studio-mixed.pdf'
GUEST = "try{localStorage.setItem('ms.guest','1')}catch(e){}"
# counts window/document listeners added by studio-toolbar.js, so re-rendering the bar cannot leak them
LEAK = """(()=>{window.__tbL=0;for(const o of [window,document]){const a=o.addEventListener;o.addEventListener=function(){if(String(new Error().stack).includes('studio-toolbar.js'))window.__tbL++;return a.apply(this,arguments)}}})()"""
MARKERS = ['#f2c230', '#7bd88f', '#6fb1ff', '#ff8fa3', '#ffb347', '#c39bff']
PENCOL = ['#168c8c', '#e43d56', '#2f6fed', '#f2c230']
def load(ctx):
    pg = ctx.new_page(); errs = []; pg.on('pageerror', lambda e: errs.append(str(e))); pg.on('dialog', lambda d: d.accept())
    pg.goto(reader(BASE, URL)); pg.wait_for_function("document.querySelectorAll('section.page').length===5", timeout=15000); pg.wait_for_timeout(500); return pg, errs
def reload(pg): pg.reload(); pg.wait_for_function("document.querySelectorAll('section.page').length===5", timeout=15000); pg.wait_for_timeout(500)
def style(pg, t): return pg.evaluate("t => MedixaStudio.style(t)", t)
def inp(pg): return pg.evaluate("MedixaStudio.input()")
def set_range(pg, sel, v): pg.evaluate("([s,v])=>{const r=document.querySelector(s);r.value=v;r.dispatchEvent(new Event('input',{bubbles:true}))}", [sel, v])
def is_open(pg, sel='#st-toolset'): return pg.evaluate("s=>{const t=document.querySelector(s);return !!t&&!t.hidden&&t.getBoundingClientRect().height>0}", sel)
def bar(t): return f'#studio-toolbar .st-tools [data-tool={t}]'
def painted(pg, sel): return pg.evaluate("s=>{const c=document.querySelector(s);if(!c||!c.width)return 0;const d=c.getContext('2d').getImageData(0,0,c.width,c.height).data;let n=0;for(let i=3;i<d.length;i+=4)if(d[i]>8)n++;return n}", sel)
def sig(pg, sel): return pg.evaluate("s=>{const c=document.querySelector(s),d=c.getContext('2d').getImageData(0,0,c.width,c.height).data;let h=0;for(let i=0;i<d.length;i+=4)h=(Math.imul(h,31)+d[i]+d[i+3])>>>0;return h}", sel)
def colors(pg, sel): return pg.eval_on_selector_all(sel, 'els => els.map(e => e.dataset.color)')
def title(pg): return pg.inner_text('#st-toolset .ts-title')
# a point outside the sheet that is not a control (the header's tab ✕ or back link would navigate away)
NEUTRAL = "(()=>{for(let y=4;y<innerHeight;y+=6)for(let x=8;x<innerWidth;x+=12){const e=document.elementFromPoint(x,y);if(e&&!e.closest('a,button,input,select,textarea,label,canvas,[role=tab],[tabindex],.st-pop,#studio-toolbar'))return [x,y]}return null})()"
def more(pg):
    if not is_open(pg, '.st-morepop'): pg.click('#studio-settings'); pg.wait_for_timeout(120)
try:
    with sync_playwright() as p:
        b = p.chromium.launch(args=['--no-sandbox'])
        # ======================= desktop =======================
        ctx = new_context(b, {URL: 'mixed.pdf'}, viewport={'width': 1280, 'height': 900}); ctx.add_init_script(GUEST); ctx.add_init_script(LEAK)
        pg, errs = load(ctx)
        l0 = pg.evaluate("window.__tbL")
        names = pg.eval_on_selector_all('#studio-toolbar [data-tool]', 'els => els.map(e => e.getAttribute("aria-label"))')
        chk(len(names) == 14 and 'سهم' in names and 'تحريك الصفحة' in names, f'arrow and hand tools added ({len(names)} tools)')
        chk(pg.evaluate("MedixaStudio.S.tool") == 'pen' and not is_open(pg), 'starts with the pen, settings closed')
        chevron = pg.evaluate("getComputedStyle(document.querySelector('#studio-toolbar .st-tools [data-tool=pen]'),'::after').content")
        chk(chevron not in ('none', 'normal', ''), f'the active tool shows a settings chevron ({chevron})')
        chk(pg.evaluate("getComputedStyle(document.querySelector('#studio-toolbar .st-tools [data-tool=eraser]'),'::after').content") in ('none', 'normal'), 'inactive tools show no chevron')
        # ---------- pen ----------
        pg.click(bar('pen')); pg.wait_for_timeout(150)
        chk(is_open(pg) and pg.get_attribute(bar('pen'), 'aria-expanded') == 'true', 'tapping the active pen opens #st-toolset')
        chk(title(pg) == 'إعدادات القلم' and pg.get_attribute('#st-toolset', 'class') == 'st-pop st-toolset', 'pen settings sheet (st-pop st-toolset)')
        chk(painted(pg, '#ts-preview') > 150, f'live preview painted ({painted(pg, "#ts-preview")} px)')
        dims = pg.evaluate("(()=>{const c=document.getElementById('ts-preview'),r=c.getBoundingClientRect();return [c.width,c.height,r.width,r.height]})()")
        chk(dims[0] == round(dims[2]) and dims[1] == round(dims[3]) and 240 <= dims[2] <= 340 and 60 <= dims[3] <= 80, f'preview ~260x70 css, backing = css x dpr ({dims})')
        chk(all(painted(pg, f'#st-toolset [data-pen={k}] canvas') > 10 for k in ('ballpoint', 'fountain', 'pencil', 'technical')), 'each pen preset chip is drawn by the renderer')
        s0 = sig(pg, '#ts-preview'); pg.click('#st-toolset [data-pen=fountain]'); pg.wait_for_timeout(100)
        chk(style(pg, 'pen')['pen'] == 'fountain' and pg.get_attribute('#st-toolset [data-pen=fountain]', 'aria-pressed') == 'true', 'choosing «قلم حبر» sets pen = fountain')
        chk(is_open(pg) and sig(pg, '#ts-preview') != s0, 'preview redraws for the new preset, sheet stays open')
        s1 = sig(pg, '#ts-preview'); set_range(pg, '#ts-smooth', 80); pg.wait_for_timeout(60)
        chk(abs(style(pg, 'pen')['smooth'] - 0.8) < 1e-9 and pg.inner_text('#st-toolset output[for=ts-smooth]') == '80%', 'smoothing slider -> smooth 0.8')
        chk(sig(pg, '#ts-preview') != s1, 'smoothing changes the preview')
        set_range(pg, '#ts-wrmin', 0.5); set_range(pg, '#ts-wrmax', 3); pg.wait_for_timeout(60)
        chk(style(pg, 'pen')['wr'] == [0.5, 3], f'pressure range sliders -> wr {style(pg, "pen")["wr"]}')
        pg.focus('#ts-wrmax'); pg.keyboard.press('End'); pg.wait_for_timeout(60)
        chk(style(pg, 'pen')['wr'][1] == 4, 'sliders work from the keyboard (End -> max 4)')
        set_range(pg, '#ts-wrmax', 3); set_range(pg, '#ts-width', 7); pg.wait_for_timeout(60)
        chk(style(pg, 'pen')['width'] == 7 and pg.input_value('#width') == '7', 'thickness slider writes the pen width (bar slider follows)')
        pg.click('#st-toolset .ts-sw[data-color="#2f6fed"]'); pg.wait_for_timeout(60)
        chk(style(pg, 'pen')['color'] == '#2f6fed' and pg.get_attribute('#studio-toolbar .st-colors .st-swatch[data-color="#2f6fed"]', 'aria-pressed') == 'true', 'sheet colour = pen colour, bar swatch follows')
        pg.uncheck('#ts-shapesnap'); chk(inp(pg)['shapeSnap'] is False, 'shape snap toggle -> input.shapeSnap false'); pg.check('#ts-shapesnap'); chk(inp(pg)['shapeSnap'] is True, 'shape snap back on')
        # closing: re-tap, Escape (focus returns), outside click
        pg.click(bar('pen')); pg.wait_for_timeout(100); chk(not is_open(pg) and pg.get_attribute(bar('pen'), 'aria-expanded') == 'false', 're-tap closes the sheet')
        pg.click(bar('pen')); pg.wait_for_timeout(100); pg.focus('#ts-smooth'); pg.keyboard.press('Escape'); pg.wait_for_timeout(100)
        chk(not is_open(pg) and pg.evaluate("document.activeElement && document.activeElement.dataset.tool") == 'pen', 'Escape closes and returns focus to the tool')
        pg.click(bar('pen')); pg.wait_for_timeout(100); pg.click('#status'); pg.wait_for_timeout(100); chk(not is_open(pg), 'outside click closes')
        pg.focus(bar('pen')); pg.keyboard.press('Enter'); pg.wait_for_timeout(150)
        chk(is_open(pg) and pg.evaluate("document.getElementById('st-toolset').contains(document.activeElement)"), 'keyboard opens the sheet and moves focus into it')
        pg.keyboard.press('Escape')
        # persisted (engine storage) and shown again after reload
        pg.wait_for_timeout(400); reload(pg); st = style(pg, 'pen')
        chk(st['pen'] == 'fountain' and abs(st['smooth'] - 0.8) < 1e-9 and st['wr'] == [0.5, 3] and st['width'] == 7 and st['color'] == '#2f6fed', f'pen settings survive a reload {st}')
        pg.click(bar('pen')); pg.wait_for_timeout(150)
        chk(pg.input_value('#ts-smooth') == '80' and float(pg.input_value('#ts-wrmin')) == 0.5 and pg.get_attribute('#st-toolset [data-pen=fountain]', 'aria-pressed') == 'true', 'sheet shows the saved values')
        pg.click(bar('pen'))
        # ---------- highlighter: marker colours in the bar and the sheet ----------
        pg.click(bar('highlight')); pg.wait_for_timeout(150)
        chk(colors(pg, '#studio-toolbar .st-colors .st-swatch') == MARKERS[:4], f'quick swatches show marker colours with the highlighter {colors(pg, "#studio-toolbar .st-colors .st-swatch")}')
        pg.click(bar('highlight')); pg.wait_for_timeout(150)
        chk(is_open(pg) and title(pg) == 'إعدادات التظليل' and colors(pg, '#st-toolset .ts-sw') == MARKERS, 'highlighter sheet: 6 marker colours')
        chk(pg.evaluate("(()=>{const t=[...document.querySelectorAll('#st-toolset .ts-colors > *')].map(e=>e.getBoundingClientRect().top);return Math.max(...t)-Math.min(...t)})()") < 2, 'marker colours + custom colour fit one row')
        set_range(pg, '#ts-op', 50); pg.wait_for_timeout(60); chk(abs(style(pg, 'highlight')['op'] - 0.5) < 1e-9, 'opacity slider -> op 0.5')
        pg.click('#st-toolset .ts-sw[data-color="#c39bff"]'); chk(style(pg, 'highlight')['color'] == '#c39bff' and style(pg, 'pen')['color'] == '#2f6fed', 'marker colour is the highlighter\'s own')
        chk(painted(pg, '#ts-preview') > 150, 'highlighter preview painted')
        pg.uncheck('#ts-straight'); pg.wait_for_timeout(60)
        chk(style(pg, 'highlight')['straight'] is False and pg.is_disabled('#ts-hsnap'), 'straight-line toggle off (horizontal snap disabled with it)')
        pg.check('#ts-straight'); pg.uncheck('#ts-hsnap'); chk(style(pg, 'highlight')['straight'] is True and style(pg, 'highlight')['hsnap'] is False, 'horizontal snap toggle'); pg.check('#ts-hsnap')
        pg.click(bar('pen')); pg.wait_for_timeout(120)
        chk(colors(pg, '#studio-toolbar .st-colors .st-swatch') == PENCOL and not is_open(pg), 'pen brings back the ink colours')
        # ---------- eraser ----------
        pg.click(bar('eraser')); pg.click(bar('eraser')); pg.wait_for_timeout(150)
        chk(is_open(pg) and title(pg) == 'إعدادات الممحاة' and pg.locator('#st-toolset .ts-seg small').count() == 2, 'eraser sheet with a one-line hint per mode')
        pg.click('#st-toolset [data-mode=precise]'); pg.wait_for_timeout(60)
        chk(style(pg, 'eraser')['mode'] == 'precise' and pg.get_attribute('#st-toolset [data-mode=precise]', 'aria-pressed') == 'true', 'segmented control -> precise eraser')
        set_range(pg, '#ts-esize', 30); pg.wait_for_timeout(60)
        chk(style(pg, 'eraser')['size'] == 30 and pg.evaluate("document.getElementById('ts-edot').getBoundingClientRect().width") == 60, 'eraser size slider + circle preview')
        pg.click('#st-toolset [data-mode=stroke]'); chk(style(pg, 'eraser')['mode'] == 'stroke', 'back to the whole-stroke eraser')
        # ---------- arrow (from «المزيد»): heads, angle snap ----------
        more(pg); pg.click('#studio-toolbar .st-morepop [data-tool=arrow]'); pg.wait_for_timeout(150)
        chk(pg.evaluate("MedixaStudio.S.tool") == 'arrow' and pg.locator('#studio-toolbar .st-tools .st-extra[data-tool=arrow]').count() == 1, 'arrow chosen from «المزيد» shows on the bar')
        pg.click(bar('arrow')); pg.wait_for_timeout(150)
        chk(is_open(pg) and title(pg) == 'إعدادات السهم' and painted(pg, '#ts-preview') > 60, 'arrow sheet with preview')
        s2 = sig(pg, '#ts-preview'); pg.click('#st-toolset [data-head=both]'); pg.wait_for_timeout(60)
        chk(style(pg, 'arrow')['head'] == 'both' and sig(pg, '#ts-preview') != s2, 'arrow head option «طرفان» (preview redraws)')
        pg.check('#ts-snap'); chk(pg.evaluate("MedixaStudio.S.snap") is True, 'angle snap from the sheet')
        more(pg); chk(pg.is_checked('#studio-snap'), '«المزيد» snap checkbox follows'); pg.uncheck('#studio-snap'); chk(pg.evaluate("MedixaStudio.S.snap") is False, '#studio-snap still works')
        # an arrow drawn on the page carries both heads (drawn inside the viewport, with «المزيد» closed first)
        pg.keyboard.press('Escape'); n0 = pg.evaluate("MedixaStudio.S.items.length"); bx = pg.locator('canvas.ink').first.bounding_box()
        pg.mouse.move(bx['x'] + 60, bx['y'] + 320); pg.mouse.down(); pg.mouse.move(bx['x'] + 260, bx['y'] + 280, steps=6); pg.mouse.up(); pg.wait_for_timeout(200)
        last = pg.evaluate("MedixaStudio.S.items[MedixaStudio.S.items.length-1]")
        chk(pg.evaluate("MedixaStudio.S.items.length") == n0 + 1 and last['tool'] == 'arrow' and last.get('head') == 'both', 'a drawn arrow uses the chosen heads')
        # ---------- long press: choose + open in one gesture ----------
        bb = pg.locator(bar('pen')).bounding_box(); pg.mouse.move(bb['x'] + bb['width'] / 2, bb['y'] + bb['height'] / 2); pg.mouse.down(); pg.wait_for_timeout(650); pg.mouse.up(); pg.wait_for_timeout(250)
        chk(pg.evaluate("MedixaStudio.S.tool") == 'pen' and is_open(pg) and title(pg) == 'إعدادات القلم', 'long press on a tool selects it and opens its settings (the trailing click does not close it)')
        pg.keyboard.press('Escape'); pg.wait_for_timeout(100)
        bb = pg.locator(bar('pen')).bounding_box()   # the bar re-rendered: the pen button moved
        pg.mouse.move(bb['x'] + bb['width'] / 2, bb['y'] + bb['height'] / 2); pg.mouse.down(); pg.wait_for_timeout(1500); pg.mouse.up(); pg.wait_for_timeout(250)
        chk(is_open(pg) and title(pg) == 'إعدادات القلم', 'a long hold (1.5 s) on the active tool still leaves its settings open')
        pg.keyboard.press('Escape')
        # ---------- hand tool ----------
        more(pg); pg.click('#studio-toolbar .st-morepop [data-tool=hand]'); pg.wait_for_timeout(150)
        chk(pg.evaluate("MedixaStudio.S.tool") == 'hand', 'hand tool selectable right after a long press elsewhere'); pg.click(bar('hand')); pg.wait_for_timeout(100)
        chk(not is_open(pg) and pg.evaluate("document.documentElement.dataset.studioTool") == 'hand', 'hand has no settings sheet; page shows the pan cursor state')
        # ---------- text ----------
        more(pg); pg.click('#studio-toolbar .st-morepop [data-tool=text]'); pg.click(bar('text')); pg.wait_for_timeout(150)
        chk(is_open(pg) and title(pg) == 'إعدادات النص', 'text sheet')
        chk(pg.evaluate("[...document.querySelectorAll('#studio-toolbar .st-size, #width')].every(e => !e.offsetParent)"), 'text: the bar hides the stroke sizes (a text has no stroke width)')
        pg.select_option('#ts-size', '24'); pg.click('#ts-bold'); pg.wait_for_timeout(60)
        chk(style(pg, 'text')['size'] == 24 and style(pg, 'text')['bold'] is True and pg.get_attribute('#ts-bold', 'aria-pressed') == 'true', 'text size 24 + bold')
        pg.click('#ts-italic'); chk(style(pg, 'text')['italic'] is True and style(pg, 'sticky')['italic'] is True, 'italic (sticky notes share the text style)')
        pg.click('#ts-bold'); pg.click('#ts-italic'); chk(painted(pg, '#ts-preview') > 40, 'text preview painted')
        pg.keyboard.press('Escape'); pg.evaluate("MedixaStudio.setTool('pen')")
        chk(pg.locator('#studio-toolbar .st-sizes .st-size').count() == 3 and all(pg.is_visible(f'#studio-toolbar .st-size[data-w="{w}"]') for w in (2, 3, 6)), 'pen: the stroke sizes are back on the bar')
        # ---------- lasso: quick colours restyle the selection ----------
        has_sel = pg.evaluate("!!MedixaStudio.selection")
        if has_sel:
            pg.evaluate("""(()=>{const s=MedixaStudio.selection;window.__sv={c:s.count,a:s.applyStyle};window.__ap=[];s.count=()=>2;s.applyStyle=p=>window.__ap.push(p)})()""")
            pg.evaluate("MedixaStudio.setTool('lasso')"); pg.wait_for_timeout(100); c0 = style(pg, 'pen')['color']
            pg.click('#studio-toolbar .st-colors .st-swatch[data-color="#e43d56"]'); pg.click('#studio-toolbar .st-sizes .st-size[data-w="6"]')
            chk(pg.evaluate("window.__ap") == [{'color': '#e43d56'}, {'width': 6}] and style(pg, 'pen')['color'] == c0, 'lasso + selection: swatch / size restyle the selection')
            pg.evaluate("(()=>{const w=document.getElementById('width');w.value=9;w.dispatchEvent(new Event('input',{bubbles:true}));w.dispatchEvent(new Event('change',{bubbles:true}))})()")
            chk(pg.evaluate("window.__ap.slice(2)") == [{'width': 9}] and pg.evaluate("MedixaStudio.S.width") != 9, 'lasso + selection: the width slider restyles the selection once')
            pg.evaluate("window.__ap.length = 2")
            pg.evaluate("MedixaStudio.selection.count=()=>0"); pg.click('#studio-toolbar .st-colors .st-swatch[data-color="#168c8c"]')
            chk(len(pg.evaluate("window.__ap")) == 2, 'no selection: swatches set the colour as before')
            pg.evaluate("(()=>{const s=MedixaStudio.selection;s.count=window.__sv.c;s.applyStyle=window.__sv.a;if(!s.count)delete s.count;if(!s.applyStyle)delete s.applyStyle})()")
        pg.evaluate("MedixaStudio.setTool('pen')")
        # ---------- lasso modes: only when the selection module offers them ----------
        real = pg.evaluate("!!(MedixaStudio.selection && MedixaStudio.selection.setMode)")
        if not real:   # without the API the lasso has no sheet (no chevron, re-tap does nothing)
            pg.evaluate("MedixaStudio.setTool('lasso')"); pg.wait_for_timeout(100); pg.click(bar('lasso')); pg.wait_for_timeout(100)
            chk(not is_open(pg) and 'st-has-set' not in (pg.get_attribute(bar('lasso'), 'class') or ''), 'lasso without selection modes: no settings sheet')
            pg.evaluate("(()=>{const s=MedixaStudio.selection;window.__fake=1;let m='free';s.mode=()=>m;s.setMode=v=>{m=v}})()")
        pg.evaluate("MedixaStudio.setTool('pen')"); pg.evaluate("MedixaStudio.setTool('lasso')"); pg.wait_for_timeout(100); pg.click(bar('lasso')); pg.wait_for_timeout(150)
        chk(is_open(pg) and title(pg) == 'إعدادات التحديد' and pg.locator('#st-toolset [data-smode]').count() == 2, 'lasso sheet: free / rectangle selection')
        pg.click('#st-toolset [data-smode=rect]'); pg.wait_for_timeout(60)
        chk('rect' in str(pg.evaluate("MedixaStudio.selection.mode()")).lower() and pg.get_attribute('#st-toolset [data-smode=rect]', 'aria-pressed') == 'true', 'rectangle selection mode set')
        pg.click('#st-toolset [data-smode=free]'); pg.wait_for_timeout(60)
        chk(pg.get_attribute('#st-toolset [data-smode=free]', 'aria-pressed') == 'true' and 'rect' not in str(pg.evaluate("MedixaStudio.selection.mode()")).lower(), 'back to free selection')
        pg.keyboard.press('Escape')
        if not real: pg.evaluate("(()=>{const s=MedixaStudio.selection;delete s.mode;delete s.setMode})()")
        pg.evaluate("MedixaStudio.setTool('pen')")
        # re-rendering the bar many times adds no window / document listeners
        for t in ('highlight', 'eraser', 'arrow', 'text', 'hand', 'pen') * 3: pg.evaluate("t => MedixaStudio.setTool(t)", t)
        pg.click(bar('pen')); pg.keyboard.press('Escape')
        chk(pg.evaluate("window.__tbL") == l0, f'no listener leak across renders ({l0} -> {pg.evaluate("window.__tbL")})')
        # ---------- «المزيد»: touch & stylus input ----------
        more(pg)
        chk(all(pg.is_visible(s) for s in ('#studio-insert-image', '#studio-finger', '#medixa-pen-only', '#studio-palm', '#studio-palm-sens', '#studio-twofinger', '#studio-autostylus', '#studio-forget-pen', '#studio-snap', '#studio-margins-btn', '#studio-customize')), '«المزيد» has image, input settings and the old settings')
        pg.uncheck('#studio-finger'); chk(inp(pg)['fingerDraw'] is False, 'finger drawing off')
        pg.check('#medixa-pen-only'); chk(inp(pg)['stylusOnly'] is True and pg.evaluate("MedixaStudio.S.penOnly") is True and pg.is_disabled('#studio-finger'), 'stylus only on (finger option greyed)')
        pg.uncheck('#medixa-pen-only'); chk(inp(pg)['stylusOnly'] is False, 'stylus only off')
        pg.uncheck('#studio-palm'); chk(inp(pg)['palm'] is False and pg.is_disabled('#studio-palm-sens'), 'palm rejection off disables its sensitivity')
        pg.check('#studio-palm'); pg.select_option('#studio-palm-sens', 'high'); chk(inp(pg)['palm'] is True and inp(pg)['palmSens'] == 'high', 'palm sensitivity high')
        pg.uncheck('#studio-twofinger'); chk(inp(pg)['twoFinger'] is False, 'two-finger navigation off')
        pg.uncheck('#studio-autostylus'); chk(inp(pg)['autoStylus'] is False, 'auto stylus off')
        reload(pg); I = inp(pg); more(pg)
        chk(I['fingerDraw'] is False and I['palmSens'] == 'high' and I['twoFinger'] is False and I['autoStylus'] is False, f'input settings persisted {I}')
        chk(not pg.is_checked('#studio-finger') and pg.input_value('#studio-palm-sens') == 'high' and not pg.is_checked('#studio-autostylus'), 'checkboxes show the saved input settings')
        pg.evaluate("MedixaStudio.setInput({fingerDraw:true, stylusOnly:false, palm:true, palmSens:'medium', twoFinger:true, autoStylus:true})"); pg.wait_for_timeout(60)
        chk(pg.is_checked('#studio-finger') and pg.input_value('#studio-palm-sens') == 'medium', 'controls follow M.setInput')
        # stylus detection status + forget
        chk(pg.inner_text('#studio-pen-status') == 'لم يُكتشف قلم بعد' and pg.is_disabled('#studio-forget-pen'), 'no stylus yet')
        pg.evaluate("MedixaStudio.markPen()"); pg.wait_for_timeout(60)
        chk(pg.evaluate("MedixaStudio.gesture.penSeen") > 0 and pg.inner_text('#studio-pen-status') == 'اكتُشف قلم على هذا الجهاز' and pg.is_enabled('#studio-forget-pen'), 'stylus detected status')
        pg.click('#studio-forget-pen'); pg.wait_for_timeout(60)
        chk(pg.evaluate("MedixaStudio.gesture.penSeen") == 0 and pg.inner_text('#studio-pen-status') == 'لم يُكتشف قلم بعد', 'forgetPen resets')
        chk('تقديري' in pg.inner_text('.st-morepop'), 'palm rejection note shown')
        # insert image: missing module -> calm banner; present -> pick()
        pg.evaluate("window.__img = MedixaStudio.images; delete MedixaStudio.images")
        pg.click('#studio-insert-image'); pg.wait_for_timeout(100)
        chk(pg.is_visible('#studio-banner.open') and 'إدراج الصور غير متاح الآن.' in pg.inner_text('#studio-banner') and not is_open(pg, '.st-morepop'), 'insert image without the module: banner, menu closed')
        pg.click('#studio-banner button'); pg.evaluate("MedixaStudio.images = {pick(){ window.__picked = (window.__picked||0) + 1 }}")
        more(pg); pg.click('#studio-insert-image'); chk(pg.evaluate("window.__picked") == 1, 'insert image calls M.images.pick()')
        pg.evaluate("if (window.__img) MedixaStudio.images = window.__img; else delete MedixaStudio.images")
        # «المزيد» fits on screen (scrolls inside, clear of the bottom dock)
        more(pg); r = pg.evaluate("(()=>{const p=document.querySelector('.st-morepop').getBoundingClientRect(),d=document.getElementById('mx-dock');return [p.top,p.bottom,innerHeight,d?d.getBoundingClientRect().top:innerHeight]})()")
        chk(r[0] >= 0 and r[1] <= min(r[2], r[3]) + 1, f'«المزيد» stays inside the viewport above the dock {r}')
        pg.keyboard.press('Escape'); chk(not is_open(pg, '.st-morepop'), 'Escape closes «المزيد» too')
        # night mode
        pg.evaluate("document.body.classList.add('medixa-dark')"); pg.click(bar('pen')); pg.wait_for_timeout(150)
        bg = pg.evaluate("getComputedStyle(document.getElementById('st-toolset')).backgroundColor"); rgb = [int(x) for x in bg[bg.index('(') + 1:bg.index(')')].split(',')[:3]]
        chk(sum(rgb) < 200, f'night mode sheet is dark ({bg})'); pg.keyboard.press('Escape'); pg.evaluate("document.body.classList.remove('medixa-dark')")
        chk(not errs, f'desktop: no page errors {errs[:3]}')
        ctx.close()
        # ======================= phone 390x844 =======================
        ctx = new_context(b, {URL: 'mixed.pdf'}, viewport={'width': 390, 'height': 844}, has_touch=True, device_scale_factor=2); ctx.add_init_script(GUEST)
        pg, errs = load(ctx)
        rows = pg.evaluate("(()=>{const r=document.getElementById('studio-toolbar'),k=[...r.querySelectorAll('.st-tools>button,.st-style button.st-stylebtn,.st-hist>button,#studio-settings')].filter(e=>e.offsetParent).map(e=>e.getBoundingClientRect());return [r.getBoundingClientRect().height,Math.max(...k.map(x=>x.top))-Math.min(...k.map(x=>x.top)),Math.max(...k.map(x=>x.right)),k.length]})()")
        chk(rows[0] <= 76 and rows[1] < 2 and rows[2] <= 390, f'phone: the bar is one row inside the screen {rows}')
        pg.locator(bar('pen')).tap(); pg.wait_for_timeout(200)
        box = pg.evaluate("(()=>{const t=document.getElementById('st-toolset').getBoundingClientRect(),b=document.getElementById('studio-toolbar').getBoundingClientRect();return [t.left,t.top,t.right,t.bottom,b.top,getComputedStyle(document.getElementById('st-toolset')).overflowY,getComputedStyle(document.getElementById('st-toolset')).position]})()")
        chk(is_open(pg) and box[0] >= 0 and box[1] >= 0 and box[2] <= 390 and box[3] <= box[4] + 1, f'phone: tapping the active pen opens a sheet inside the viewport, above the bar {box[:5]}')
        chk(box[0] <= 12 and box[2] >= 378, f'phone: the sheet spans the screen width (8px gutters) {box[:3]}')
        chk(box[5] in ('auto', 'scroll') and box[6] == 'fixed', 'phone: the sheet is a fixed, scrollable bottom sheet')
        dims = pg.evaluate("(()=>{const c=document.getElementById('ts-preview'),r=c.getBoundingClientRect();return [c.width,r.width]})()")
        chk(dims[0] == round(dims[1] * 2) and painted(pg, '#ts-preview') > 150, f'phone: preview is DPR-aware and painted {dims}')
        pg.click('#st-toolset [data-pen=pencil]'); chk(style(pg, 'pen')['pen'] == 'pencil', 'phone: preset chips work')
        tb = pg.locator('#ts-wrmax').bounding_box(); chk(tb['x'] >= 0 and tb['x'] + tb['width'] <= 390, 'phone: sliders fit the sheet')
        spot = pg.evaluate(NEUTRAL); chk(spot is not None, f'phone: a neutral spot outside the sheet {spot}')
        pg.touchscreen.tap(*spot); pg.wait_for_timeout(150); chk(not is_open(pg) and pg.evaluate("!!window.MedixaStudio"), 'phone: tapping outside closes the sheet')
        # long press with a finger (CDP touch) on the highlighter
        cdp = ctx.new_cdp_session(pg); hb = pg.locator(bar('highlight')).bounding_box(); x, y = hb['x'] + hb['width'] / 2, hb['y'] + hb['height'] / 2
        cdp.send('Input.dispatchTouchEvent', dict(type='touchStart', touchPoints=[dict(x=x, y=y)])); pg.wait_for_timeout(700)
        cdp.send('Input.dispatchTouchEvent', dict(type='touchEnd', touchPoints=[])); pg.wait_for_timeout(250)
        chk(pg.evaluate("MedixaStudio.S.tool") == 'highlight' and is_open(pg) and title(pg) == 'إعدادات التظليل', 'phone: long press opens the highlighter sheet')
        hb2 = pg.evaluate("(()=>{const t=document.getElementById('st-toolset');return [t.getBoundingClientRect().top,t.getBoundingClientRect().bottom,t.scrollHeight>=t.clientHeight]})()")
        chk(hb2[0] >= 0 and hb2[1] <= 844 and hb2[2], f'phone: highlighter sheet inside the viewport {hb2}')
        pg.locator(bar('highlight')).tap(); pg.wait_for_timeout(150); chk(not is_open(pg), 'phone: re-tap closes')
        pg.locator('#studio-settings').tap(); pg.wait_for_timeout(150)
        mb = pg.evaluate("(()=>{const t=document.querySelector('.st-morepop').getBoundingClientRect();return [t.left,t.top,t.right,t.bottom]})()")
        chk(is_open(pg, '.st-morepop') and mb[0] >= 0 and mb[1] >= 0 and mb[2] <= 390 and mb[3] <= 844, f'phone: «المزيد» sheet inside the viewport {mb}')
        hs = pg.evaluate("Math.round(document.getElementById('studio-palm-sens').getBoundingClientRect().height)"); chk(hs >= 44, f'phone: palm sensitivity select is a 44px target ({hs})')
        # long press on a tool inside «المزيد»: the sheet opens where the finger is; the trailing tap must not close it or press a control
        n0 = pg.evaluate("MedixaStudio.S.items.length"); s0 = json.dumps([style(pg, 'shape'), pg.evaluate("MedixaStudio.S.snap")])
        ab = pg.locator('#studio-toolbar .st-morepop [data-tool=arrow]').bounding_box(); x, y = ab['x'] + ab['width'] / 2, ab['y'] + ab['height'] / 2
        cdp.send('Input.dispatchTouchEvent', dict(type='touchStart', touchPoints=[dict(x=x, y=y)])); pg.wait_for_timeout(700)
        cdp.send('Input.dispatchTouchEvent', dict(type='touchEnd', touchPoints=[])); pg.wait_for_timeout(300)
        chk(pg.evaluate("MedixaStudio.S.tool") == 'arrow' and is_open(pg) and title(pg) == 'إعدادات السهم', 'phone: long press on a tool in «المزيد» opens its sheet and keeps it open')
        chk(json.dumps([style(pg, 'shape'), pg.evaluate("MedixaStudio.S.snap")]) == s0 and pg.evaluate("MedixaStudio.S.items.length") == n0, 'phone: that long press changes no setting and draws nothing')
        pg.locator('#ts-close').tap(); pg.wait_for_timeout(150)
        # a long finger hold (1.5 s) on a bar tool: still open after the finger lifts, no text selected, nothing drawn
        eb = pg.locator(bar('eraser')).bounding_box(); x, y = eb['x'] + eb['width'] / 2, eb['y'] + eb['height'] / 2
        cdp.send('Input.dispatchTouchEvent', dict(type='touchStart', touchPoints=[dict(x=x, y=y)])); pg.wait_for_timeout(1500)
        cdp.send('Input.dispatchTouchEvent', dict(type='touchEnd', touchPoints=[])); pg.wait_for_timeout(300)
        chk(pg.evaluate("MedixaStudio.S.tool") == 'eraser' and is_open(pg) and title(pg) == 'إعدادات الممحاة' and pg.evaluate("String(getSelection())") == '' and pg.evaluate("MedixaStudio.S.items.length") == n0, 'phone: a 1.5 s hold opens the eraser sheet and leaves it open')
        pg.locator(bar('eraser')).tap(); pg.wait_for_timeout(150); chk(not is_open(pg), 'phone: the next tap on the tool closes it as usual')
        chk(not errs, f'phone: no page errors {errs[:3]}')
        b.close()
finally:
    srv.terminate()
chk.done()
